def calculate_bmi(weight, height):
    bmi = weight / (height ** 2)
    return round(bmi, 1)

def create_greeting(name, greeting_type='friendly'):
    if greeting_type == 'formal':
        return f'Dear {name}'
    elif greeting_type == 'casual':
        return f'Hey {name}!'
    else:  # friendly (default)
        return f'Hello {name}!'

def convert_temperature(temp, unit):
    if unit == 'C':
        # Convert Celsius to Fahrenheit
        converted = (temp * 9/5) + 32
    elif unit == 'F':
        # Convert Fahrenheit to Celsius
        converted = (temp - 32) * 5/9
    else:
        return 'Invalid unit'

    return round(converted, 1)

def validate_credit_card(card_number):
    # Check length
    if len(card_number) != 16:
        return False

    # Check if all characters are digits
    if not card_number.isdigit():
        return False

    # Check starting digit
    if card_number[0] not in ['4', '5', '6']:
        return False

    return True

def calculate_compound_interest(principal, rate, time, frequency=1):
    amount = principal * (1 + rate/frequency) ** (frequency * time)
    return round(amount, 2)
